mapper.select:
SELECT
    COUNT(*) AS executeCount,
    COUNT(DISTINCT workflow_id) AS workflowCount,
    COALESCE(ROUND(AVG(duration_ms)), 0) AS avgDurationMs,
    COALESCE(ROUND(AVG(actual_node_count), 2), 0) AS avgNodeCount
FROM workflow_execution
WHERE user_id = #{userId}
  AND start_time >= #{dayStart}
  AND start_time < #{dayEnd}

SELECT
    stat_date AS statDate,
    execute_count AS executeCount,
    avg_duration_ms AS avgDurationMs,
    avg_actual_node_count AS avgNodeCount
FROM workflow_execution_daily_stat
WHERE user_id = #{userId}
  AND stat_date >= #{startDate}
  AND stat_date <= #{endDate}
ORDER BY stat_date

SELECT
    DATE_FORMAT(FROM_UNIXTIME(start_time / 1000), '%Y-%m-%d') AS statDate,
    COUNT(*) AS executeCount,
    COALESCE(ROUND(AVG(duration_ms)), 0) AS avgDurationMs,
    COALESCE(ROUND(AVG(actual_node_count), 2), 0) AS avgNodeCount
FROM workflow_execution
WHERE user_id = #{userId}
  AND start_time >= #{startTime}
  AND start_time < #{endTime}
GROUP BY DATE_FORMAT(FROM_UNIXTIME(start_time / 1000), '%Y-%m-%d')
